t.id 	left join tblapplication_personal_verification_details tapvd on tapvd.application_no=tar.applicationno left join ct_user usr on tar.checked_by=usr.userid left join public.tblcity cty on tar.city=cty.cityid left join public.tblprovince prov on tar.province=prov.province_id left join public.tblbarangay bar on tar.barangay=bar.id where tar.applicationno='{0}';";
        public const string GetApplicationforApprover = "Select distinct first_name,middle_name,last_name,appRec.applicationno, appRec.user_id, personalemail,jumioreference,facemapstatus,personalcontactno,to_char(appRec.dateapplied,'DD-MM-YYYY') as dateapplied,appRec.gross_income,appPerVerDet.approved_loan_amount, ispickedapprover, usr.username from tblapplication_record appRec join tblapplication_user b on appRec.user_id=b.id left join tblapplication_personal_verification_details appPerVerDet on appPerVerDet.application_no =appRec.applicationno left join ct_user usr  on appRec.verify_by = usr.userid where appRec.ischeck='true' and appRec.isverified='true' and appRec.isrecheck='false' and appRec.isreverified='false' and appRec.isapproved='false' and isdeleted=false order by appRec.applicationno ;";
