        public const string GetPortfolioList = "select distinct first_name,middle_name,last_name, t_a_r.dateapplied, t_a_r.term,lower(ttt.termtype) as termtype ,tt.term_value, t_a_r.applicationno, t_a_c_d.contract_no, t_a_c_d.contract_ref_no, t_a_p_v_d.approved_loan_amount, t_a_p_v_d.approved_term, t_a_p_v_d.approved_interest_rate, to_char(t_a_p_v_d.approved_maturity_date,'DD-MM-YYYY') as approved_maturity_date,t_a_p_v_d.approved_total_amount_due,t_a_e.reference_no, to_char(t_a_e.disbursement_date,'DD-MM-YYYY') as disbursement_date, personalemail,jumioreference,facemapstatus, personalcontactno, t_a_r.relativecontactno, t_a_r.coworkercontactno, t_a_r.address,t_a_r.province, t_a_r.city,t_a_r.industry, t_a_r.sss_no, t_a_r.barangay, t_a_r.homephoneno, t_a_r.placeofbirth, to_char(t_a_r.dateofbirth, 'DD-MM-YYYY') as dateofbirth, t_a_r.civilstatus, t_a_r.mothermaidenname, t_a_r.motheraddress, t_a_r.companyname, t_a_r.companyaddress, t_a_r.designation, t_a_r.gross_income, t_a_r.reference_name, civ.civilname, ptp.non_payment_reason, ptp.other_remarks, ptp.best_time_callback, to_char(ptp.current_date_ptp, 'DD-MM-YYYY') as current_date_ptp, emi.penality_amount1, emi.penality_amount2, emi.penality_amount3, emi.penality_amount4, emi.penality_amount5, emidetail.paidamount, emidetail.balanceamount from tblapplication_record t_a_r join tblapplication_user b on t_a_r.user_id=b.id join tbl_application_contract_details t_a_c_d on  t_a_c_d.application_no=t_a_r.applicationno join tblapplication_personal_verification_details t_a_p_v_d on t_a_p_v_d.application_no=t_a_r.applicationno join tblcivil_status civ on t_a_r.civilstatus= civ.civilid join tblapplication_ptp_details ptp on t_a_r.applicationno= ptp.application_on join tblterm_type ttt on ttt.id=t_a_r.termtype	join tblterms tt on tt.id=t_a_r.term left join tblapplication_emi t_a_e on t_a_e.application_no= t_a_r.applicationno left join tblapplication_emi emi on t_a_r.applicationno= emi.application_no left join tblapplication_emi_payment pay on t_a_r.applicationno= pay.application_no left join tblapplication_emi_details emidetail on emi.emi_id= emidetail.emi_id;";
