        public const string NewGetPaymentBucketList = "SELECT DISTINCT t_a_r.applicationno, t_a_e_d.emi_detail_id, ((now()::date) - t_a_e_d.emi_date) as aging, '1' as priority, '0' as sortingorder FROM tblapplication_record t_a_r join tblapplication_user b on t_a_r.user_id=b.id join tblterm_type t_t on t_a_r.termtype = t_t.id left join tbl_application_contract_details tcd on tcd.application_no= t_a_r.applicationno left join tblapplication_emi t_a_e on t_a_e.application_no= t_a_r.applicationno left join tblapplication_emi_details t_a_e_d on t_a_e_d.emi_id= t_a_e.emi_id left join tblapplication_ptp_details t_a_p_d on t_a_p_d.application_on= t_a_r.applicationno inner join tblemi_collection_agent_mapping colmap on t_a_e.emi_id=colmap.emi_id where  (t_a_e_d.emi_date= current_date) and t_a_e_d.balanceamount!=0 and t_a_r.applicationno not in (Select application_no from tblapplication_emi_payment where paid_on = current_date and amount_paid>0) and t_a_r.applicationno not in (Select application_on from tblapplication_ptp_details where createdon :: date = current_date and current_date_ptp > current_date)  and t_a_r.isdefaulter=false and t_a_r.is_pay= false and colmap.agent_id='{0}' and balanceamount!=0 and t_a_e_d.emi_amount>0 and t_a_r.ispretermgenerated=false union all (SELECT DISTINCT t_a_r.applicationno ,t_a_e_d.emi_detail_id, ((now()::date) - t_a_e_d.emi_date) as aging, '2' as priority, '1' FROM tblapplication_record t_a_r join tblapplication_user b on t_a_r.user_id=b.id join tblterm_type t_t on t_a_r.termtype = t_t.id left join tbl_application_contract_details tcd on tcd.application_no= t_a_r.applicationno left join tblapplication_emi t_a_e on t_a_e.application_no= t_a_r.applicationno left join tblapplication_emi_details t_a_e_d on t_a_e_d.emi_id= t_a_e.emi_id left join tblapplication_ptp_details t_a_p_d on t_a_p_d.application_on= t_a_r.applicationno inner join tblemi_collection_agent_mapping colmap on t_a_e.emi_id=colmap.emi_id where t_a_p_d.current_date_ptp= current_date and t_a_r.applicationno not in (Select application_no from tblapplication_emi_payment where paid_on = current_date and paid_amount>0) and t_a_r.isdefaulter=false and t_a_r.is_pay= false and t_a_r.is_ptp= true and colmap.agent_id='{0}' and balanceamount!=0 and t_a_e_d.emi_amount>0 and t_a_r.ispretermgenerated=false order by emi_detail_id) union all (select distinct emi.application_no, emidetails.emi_detail_id, ((now()::date) - emidetails.emi_date) as aging, '3' as priority, '2' from tblapplication_emi_details emidetails join tblapplication_emi emi on emi.emi_id=emidetails.emi_id join tblapplication_record appRecord on appRecord.applicationno= emi.application_no  join tblapplication_user b on appRecord.user_id=b.id left join tblapplication_ptp_details t_a_p_d on appRecord.applicationno = t_a_p_d.application_on join tblterm_type t_t on appRecord.termtype = t_t.id left join tbl_application_contract_details tcd on tcd.application_no= appRecord.applicationno inner join tblemi_collection_agent_mapping colmap on emi.emi_id=colmap.emi_id where emidetails.emi_date<current_date and emidetails.balanceamount!=0 and appRecord.isdefaulter=false and appRecord.is_pay=false  and colmap.agent_id='{0}' and balanceamount!=0  and appRecord.applicationno not in (Select application_on from tblapplication_ptp_details where createdon :: date = current_date and current_date_ptp > current_date) and emidetails.emi_amount>0 and appRecord.ispretermgenerated=false order by emi_detail_id) order by sortingorder;";
