        public const string GetAgingData = "SELECT distinct ((now()::date)-taed.emi_date) as age,to_char(taed.emi_date,'DD-MM-YYYY') as emi_date,(SELECT Count(taedd.emi_amount) FROM tblapplication_emi_details taedd join tblapplication_emi tblemi on taedd.emi_id=tblemi.emi_id join tblapplication_record tblrecord on tblrecord.applicationno=tblemi.application_no where tblrecord.iscompleted=false and taedd.emi_date = taed.emi_date) AS TotalMeturity,(SELECT round(COALESCE(SUM(taedd.emi_amount),0),2) FROM tblapplication_emi_details taedd join tblapplication_emi tblemi on taedd.emi_id=tblemi.emi_id join tblapplication_record tblrecord on tblrecord.applicationno=tblemi.application_no where tblrecord.iscompleted=false and taedd.emi_date = taed.emi_date) AS TotalMeturityAmount,(SELECT Count(taedd.paidamount) FROM tblapplication_emi_details taedd where taedd.emi_date = taed.emi_date and taedd.paidamount>0) AS Totalpaid,(SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd  join tblapplication_emi tblemi on taedd.emi_id=tblemi.emi_id join tblapplication_record tblrecord on tblrecord.applicationno=tblemi.application_no where tblrecord.iscompleted=false and taedd.emi_date = taed.emi_date) AS TotalpaidAmount,(CAST(((SELECT cast(Count(taedd.paidamount) as numeric(18,2)) FROM tblapplication_emi_details taedd  join tblapplication_emi tblemi on taedd.emi_id=tblemi.emi_id join tblapplication_record tblrecord on tblrecord.applicationno=tblemi.application_no where tblrecord.iscompleted=false and taedd.emi_date = taed.emi_date and taedd.paidamount>0)/(SELECT CASE WHEN Count(taedd.emi_amount)=0 then 1.0 else cast(Count(taedd.emi_amount) as numeric(18,2)) end FROM tblapplication_emi_details taedd  join tblapplication_emi tblemi on taedd.emi_id=tblemi.emi_id join tblapplication_record tblrecord on tblrecord.applicationno=tblemi.application_no where tblrecord.iscompleted=false and taedd.emi_date = taed.emi_date))as numeric(18,2))*100) AS NoCollection,Round((((SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd  join tblapplication_emi tblemi on taedd.emi_id=tblemi.emi_id join tblapplication_record tblrecord on tblrecord.applicationno=tblemi.application_no where tblrecord.iscompleted=false and taedd.emi_date = taed.emi_date)/(SELECT CASE WHEN COALESCE(SUM(taedd.emi_amount),0)=0 then 1 else COALESCE(SUM(taedd.emi_amount),0) end FROM tblapplication_emi_details taedd  join tblapplication_emi tblemi on taedd.emi_id=tblemi.emi_id join tblapplication_record tblrecord on tblrecord.applicationno=tblemi.application_no where tblrecord.iscompleted=false and taedd.emi_date=taed.emi_date))*100),2) AS NoCollectionAmount,(select count(approved_loan_amount) FROM tblapplication_record join public.tblapplication_personal_verification_details on tblapplication_record.applicationno=tblapplication_personal_verification_details.application_no and tblapplication_record.isdisbursedexport=true join tblterms on tblterms.id=tblapplication_record.term where tblapplication_record.isfor_reloan = 'false' and tblapplication_record.is_preterm='false' and to_char(disbursement_date,'DD-MM-YYYY')=to_char(taed.emi_date,'DD-MM-YYYY')) AS freshloan_count,ROUND((select coalesce(sum(((approved_loan_amount*admin_fee)/100)),0.00) FROM tblapplication_record join public.tblapplication_personal_verification_details on tblapplication_record.applicationno=tblapplication_personal_verification_details.application_no and tblapplication_record.isdisbursedexport=true join tblterms on tblterms.id=tblapplication_record.term where tblapplication_record.isfor_reloan = 'false' and tblapplication_record.is_preterm='false' and to_char(disbursement_date,'DD-MM-YYYY')=to_char(taed.emi_date,'DD-MM-YYYY')),2) AS freshloan_amount,(select count(approved_loan_amount) FROM tblapplication_record join public.tblapplication_personal_verification_details on tblapplication_record.applicationno=tblapplication_personal_verification_details.application_no and tblapplication_record.isdisbursedexport=true join tblterms on tblterms.id=tblapplication_record.term where tblapplication_record.isfor_reloan = 'true' and tblapplication_record.is_preterm='false' and to_char(disbursement_date,'DD-MM-YYYY')=to_char(taed.emi_date,'DD-MM-YYYY')) AS reloan_count,ROUND((select coalesce(sum(((approved_loan_amount*admin_fee)/100)),0.00) FROM tblapplication_record join public.tblapplication_personal_verification_details on tblapplication_record.applicationno=tblapplication_personal_verification_details.application_no and tblapplication_record.isdisbursedexport=true join tblterms on tblterms.id=tblapplication_record.term where tblapplication_record.isfor_reloan = 'true' and tblapplication_record.is_preterm='false' and to_char(disbursement_date,'DD-MM-YYYY')=to_char(taed.emi_date,'DD-MM-YYYY')),2) AS reloan_amount,((SELECT Count(taedd.emi_amount) FROM tblapplication_emi_details taedd where taedd.emi_date = taed.emi_date)-(SELECT Count(taedd.paidamount) FROM tblapplication_emi_details taedd where taedd.emi_date = taed.emi_date and taedd.paidamount>0)) AS NoDefault,((SELECT round(COALESCE(SUM(taedd.emi_amount),0),2) FROM tblapplication_emi_details taedd where taedd.emi_date = taed.emi_date)-(SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd where taedd.emi_date = taed.emi_date)) AS NoDefaultAmount FROM tblapplication_personal_verification_details tapvd join public.tblapplication_emi tae on tapvd.application_no=tae.application_no left join tblapplication_emi_details taed on tae.emi_id= taed.emi_id order by age desc;";
        public const string GetAgingTempData = "SELECT details.emi_date, details.emi_amount, details.paidamount,details.balanceamount, verify.approved_loan_amount, term.admin_fee, record.iscompleted, record.isfor_reloan, record.is_preterm, emi.disbursement_date, mappings.created_on, record.isdefaulter FROM tblapplication_record record JOIN tblterms term on term.id=record.term JOIN tblapplication_personal_verification_details verify ON RECORD.applicationno=verify.application_no JOIN tblapplication_emi emi ON emi.application_no=verify.application_no JOIN tblapplication_emi_details details ON emi.emi_id=details.emi_id LEFT JOIN tbl_application_defaulter_mapping mappings on emi.application_no=mappings.application_no order by emi_date;";
