        public const string GetPaymentBucketListByDate = "SELECT DISTINCT t_a_r.applicationno, to_char(dateapplied,'DD-MM-YYYY') as dateapplied, first_name,last_name,middle_name, personalemail,jumioreference,facemapstatus, personalcontactno, t_a_c_d.contract_ref_no, to_char(t_a_e_d.emi_date,'DD-MM-YYYY') as emi_date, to_char(t_a_p_d.current_date_ptp,'DD-MM-YYYY') as current_date_ptp FROM tblapplication_record t_a_r join tblapplication_user b on t_a_r.user_id=b.id join tbl_application_contract_details t_a_c_d on t_a_c_d.application_no=t_a_r.applicationno join tblapplication_emi t_a_e on t_a_e.application_no= t_a_r.applicationno join tblapplication_emi_details t_a_e_d on t_a_e_d.emi_id= t_a_e.emi_id left join tblapplication_ptp_details t_a_p_d on t_a_p_d.application_on= t_a_r.applicationno where t_a_r.applicationno not in (Select application_no from tblapplication_emi_payment  where paid_on = current_date and amount_paid>0) and (t_a_e_d.emi_date='{0}' or t_a_p_d.current_date_ptp='{0}');";
        public const string GetApprovedPendingPaymentsInfo = "SELECT first_name,last_name,middle_name,app.applicationno, personalcontactno, pay.payment_id, pay.paid_amount, to_char(pay.paid_on, 'dd-MM-yyyy') as paid_on, pay.whatpaymentchennel, pay.proofofpayment, pay.paymentapproved, pay.isdeleted, pay.penalty_amount, pay.remarks, emi.reference_no FROM tblapplication_record app join tblapplication_user b on app.user_id=b.id Left Join tblapplication_emi_payment pay on pay.application_no=app.applicationno Left Join tblapplication_emi emi on app.applicationno=emi.application_no where pay.isdeleted=false and pay.paymentapproved=true and app.applicationno='{0}' and pay.paid_amount>0;";
