        public const string GetPendingPaymentsData = "SELECT distinct app.user_id,first_name,last_name,middle_name,app.applicationno, personalcontactno, pay.payment_id,pay.paid_amount, pay.paid_on, pay.whatpaymentchennel, pay.proofofpayment, pay.paymentapproved, pay.isdeleted, pay.penalty_amount, pay.remarks, emi.reference_no, tacd.contract_no, tacd.contract_ref_no, tapcd.approved_loan_amount, (pay.penalty_amount + pay.paid_amount) as totalamt,'0' as emi_payment, app.checker_remark FROM tblapplication_record app join tblapplication_user b on app.user_id=b.id Left Join tblapplication_emi_payment pay on pay.application_no=app.applicationno Left Join tblapplication_emi emi on app.applicationno=emi.application_no Left Join tbl_application_contract_details tacd on pay.application_no = tacd.application_no LEFT JOIN tblapplication_emi_details taed on taed.emi_id = emi.emi_id Left Join tblapplication_personal_verification_details tapcd on app.applicationno =tapcd.application_no where pay.isdeleted=false and pay.paymentapproved=false and (pay.penalty_amount + pay.paid_amount)> 0 UNION ALL Select distinct app.user_id,first_name,last_name,middle_name,app.applicationno, personalcontactno,tdp.deferment_id as payment_id,0 as paid_amount, tdp.deferment_date as paid_on,tdp.payment_channel,tdp.proof_of_payment,tdp.payment_approved,tdp.is_deleted, tdp.late_penalty_amount as penalty_amount, pay.remarks as remarks,emi.reference_no as reference_no, tacd.contract_no as contract_no, tacd.contract_ref_no as contract_ref_no, tapcd.approved_loan_amount as approved_loan_amount,(tdp.late_penalty_amount + tdp.deferment_amount) as totalamt ,'1' as emi_payment, app.checker_remark FROM tbl_deferment_pay tdp left join tblapplication_emi emi on emi.emi_id = tdp.emi_id left join tblapplication_emi_details taed on taed.emi_id = emi.emi_id left join tblapplication_record app on app.applicationno=emi.application_no join tblapplication_user b on app.user_id=b.id Left Join tblapplication_personal_verification_details tapcd on tapcd.application_no=app.applicationno  Left Join tblapplication_emi_payment pay on pay.application_no=app.applicationno Left Join tbl_application_contract_details tacd on app.applicationno = tacd.application_no where tdp.is_deleted=false and tdp.payment_approved=false and (tdp.late_penalty_amount + tdp.deferment_amount)>0;";
