        public const string GetEmiNotCreatedNew = "select t_a_r.applicationno, first_name, middle_name, last_name, t_a_r.applicationno, t_a_r.ispickedforaccount, t_a_r.disbursement_date, t_a_c_d.contract_no, t_a_c_d.contract_ref_no, t_a_p_v_d.approved_loan_amount, tt.term_name as term_name, tt.term_value as approved_term, tt.interest_rate as approved_interest_rate,to_char(t_a_p_v_d.approved_maturity_date,'DD-MM-YYYY') as approved_maturity_date,t_a_p_v_d.approved_total_amount_due,'0' emi_status from tblapplication_record t_a_r join tblapplication_user b on t_a_r.user_id=b.id left join tbl_application_contract_details t_a_c_d on  t_a_c_d.application_no=t_a_r.applicationno 	join tblapplication_personal_verification_details t_a_p_v_d on t_a_p_v_d.application_no=t_a_r.applicationno left join tblterms tt on t_a_r.term=tt.id where t_a_r.disbursement_date::date between '{0}'::date and '{1}'::date and t_a_r.applicationno not in (select application_no from tblapplication_emi) and t_a_r.isfordisbursement = true union all select t_a_r.applicationno, first_name, middle_name,last_name,t_a_r.applicationno, t_a_r.ispickedforaccount, t_a_r.disbursement_date, t_a_c_d.contract_no, t_a_c_d.contract_ref_no, t_a_p_v_d.approved_loan_amount, tt.term_name as term_name, tt.term_value as approved_term, tt.interest_rate as approved_interest_rate, to_char(t_a_p_v_d.approved_maturity_date,'DD-MM-YYYY') as approved_maturity_date, t_a_p_v_d.approved_total_amount_due, '1' from tblapplication_record t_a_r join tblapplication_user b on t_a_r.user_id=b.id join tbl_application_contract_details t_a_c_d on  t_a_c_d.application_no=t_a_r.applicationno 	join tblapplication_personal_verification_details t_a_p_v_d on t_a_p_v_d.application_no=t_a_r.applicationno left join tblterms tt on t_a_r.term=tt.id where t_a_r.disbursement_date::date between '{0}'::date and '{1}'::date and  t_a_r.applicationno in (select application_no from tblapplication_emi) and t_a_r.isfordisbursement = true";
