        public const string GetAgencyData = "select distinct pvd.approved_total_amount_due, to_char(emi.disbursement_date,'DD-MM-YYYY') as disbursement_date, ar.applicationno, personalcontactno, personalemail,jumioreference,facemapstatus,ar.address,ar.city,ar.barangay,ar.province, first_name,city.cityname,bar.barangay_name,pro.province_name, middle_name, last_name,to_char(ar.dateapplied,'DD-MM-YYYY') as dateapplied,emi.reference_no,to_char(ar.escalate_date,'DD-MM-YYYY') as escalate_date,(SELECT to_char(current_date_ptp,'DD-MM-YYYY')  FROM tblapplication_ptp_details  where tblapplication_ptp_details.application_on=ar.applicationno ORDER BY current_date_ptp DESC LIMIT 1) as ptp_date,coalesce((select coalesce(sum(tblapplication_emi_details.balanceamount),0) from tblapplication_emi_details where tblapplication_emi_details.emi_id = t_a_e.emi_id and tblapplication_emi_details.emi_date <= current_date),0) as total_amount_due,coalesce((select coalesce(sum(tblapplication_emi_details.balanceamount),0) from tblapplication_emi_details where tblapplication_emi_details.emi_id = t_a_e.emi_id),0) as outstanding_amount,(select to_char(tblapplication_emi_details.emi_date,'DD-MM-YYYY') from tblapplication_emi_details where tblapplication_emi_details.emi_id = t_a_e.emi_id order by emi_detail_id desc limit 1) as maturity_date,DATE_PART('day', now() - acd.created_on) as aging1, (select to_char(tblapplication_emi_details.emi_date,'DD-MM-YYYY') from tblapplication_emi_details where tblapplication_emi_details.emi_id = t_a_e.emi_id order by emi_detail_id limit 1) as emi_date from tblapplication_record ar join tblapplication_user b on ar.user_id=b.id join tbl_application_defaulter_mapping acd on acd.application_no=ar.applicationno join tblapplication_emi emi on emi.application_no= ar.applicationno left join tblapplication_emi t_a_e on t_a_e.application_no= ar.applicationno left join tblapplication_personal_verification_details pvd on ar.applicationno= pvd.application_no left join tblbarangay 