        public const string GetSalesData = "SELECT distinct (SELECT Count(taedd.emi_amount)  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS TotalMaturity,(SELECT coalesce(round(SUM(taedd.emi_amount),2),0)  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS TotalMaturityAmount,(SELECT Count(taedd.paidamount) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date  between '{0}'::date and '{1}'::date and taedd.paidamount>0 and map.agent_id='{2}') AS Totalpaid,(SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date  between '{0}'::date and '{1}'::date and map.agent_id='{2}' ) AS TotalpaidAmount,(CAST(((SELECT cast(Count(taedd.paidamount) as numeric(10,2)) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date  between '{0}'::date and '{1}'::date and taedd.paidamount>0 and map.agent_id='{2}' )/(SELECT CASE WHEN Count(taedd.emi_amount)=0 then 1.0 else cast(Count(taedd.emi_amount) as numeric(10,2)) end  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date  between '{0}'::date and '{1}'::date and  map.agent_id='{2}'))as numeric(10,2))*100) AS efficiency_no,Round((((SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd  inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date  between '{0}'::date and '{1}'::date and  map.agent_id='{2}')/(SELECT CASE WHEN COALESCE(SUM(taedd.emi_amount),0)=0 then 1 else COALESCE(SUM(taedd.emi_amount),0) end FROM tblapplication_emi_details taedd  inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id  where taedd.emi_date::date  between '{0}'::date and '{1}'::date and  map.agent_id='{2}'))*100),2) AS efficiency_amount,(SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.is_preterm = true and emi.disbursement_date::date  between '{0}'::date and '{1}'::date and map.agent_id='{2}' ) AS Preterm_No,(SELECT coalesce(round(SUM(tapvd.approved_loan_amount-((tapvd.approved_loan_amount*terms.admin_fee)/100)),2),0) FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no join tblterms terms on terms.id = tar.term inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.is_preterm = true and emi.disbursement_date::date  between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS Preterm_Amount, (SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no  inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.isfor_reloan= true and emi.disbursement_date::date  between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS Reloan_No,(SELECT coalesce(round(SUM(tapvd.approved_loan_amount-((tapvd.approved_loan_amount*terms.admin_fee)/100)),2),0) FROM  tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no join tblterms terms on terms.id = tar.term  inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.isfor_reloan = true and emi.disbursement_date::date  between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS Reloan_Amount;";
        public const string GetSalesData_Yearly = "SELECT distinct (SELECT Count(taedd.emi_amount)  FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date) AS TotalMaturity,(SELECT round(SUM(taedd.emi_amount),2)  FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date) AS TotalMaturityAmount,(SELECT Count(taedd.paidamount) FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date and taedd.paidamount>0) AS Totalpaid,(SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date) AS TotalpaidAmount,(CAST(((SELECT cast(Count(taedd.paidamount) as numeric(18,2)) FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date and taedd.paidamount>0)/(SELECT CASE WHEN Count(taedd.emi_amount)=0 then 1.0 else cast(Count(taedd.emi_amount) as numeric(18,2)) end  FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date))as numeric(18,2))*100) AS efficiency_no,Round((((SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date)/(SELECT CASE WHEN COALESCE(SUM(taedd.emi_amount),0)=0 then 1 else SUM(taedd.emi_amount) end FROM tblapplication_emi_details taedd where taedd.emi_date::date between '{0}'::date and '{1}'::date))*100),2) AS efficiency_amount,(SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no where tar.is_preterm = true and tar.preterm_date::date between '{0}'::date and '{1}'::date) AS Preterm_No, (SELECT round(SUM(tapvd.approved_loan_amount-((tapvd.approved_loan_amount*terms.admin_fee)/100)),2) FROM     tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no join tblterms terms on terms.id = tar.term where tar.is_preterm = true and tar.preterm_date::date between '{0}'::date and '{1}'::date) AS Preterm_Amount, (SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no where tar.isfor_reloan= true and tar.reloan_date::date between '{0}'::date and '{1}'::date) AS Reloan_No, (SELECT round(SUM(tapvd.approved_loan_amount),2) FROM     tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no where tar.isfor_reloan = true and tar.reloan_date::date between '{0}'::date and '{1}'::date) AS Reloan_Amount from ct_user us left join tblemi_collection_agent_mapping tcam on tcam.agent_id = us.userid where us.userid = '{2}';";
