        public const string GetFSDetailsForAdmin = " select distinct record.applicationno, (SELECT paid_on  FROM tblapplication_emi_payment where tblapplication_emi_payment.application_no=emi.application_no ORDER BY paid_on DESC LIMIT 1) as fs_date, first_name,record.term,(select term_name from  tblterms where tblterms.id=record.term ) as termplan, personalemail,jumioreference,facemapstatus,(select COALESCE(sum(emi_amount),0) from tblapplication_emi_details where tblapplication_emi_details.emi_id=emi.emi_id) as amount,(select count(*) from tblapplication_emi_details where tblapplication_emi_details.emi_id=emi.emi_id ) as records, coalesce(record.isfor_reduceloan,false) as is_reduceloan,(select COALESCE(sum(balanceamount),0) from tblapplication_emi_details where tblapplication_emi_details.emi_id=emi.emi_id) as balance, personalcontactno from tblapplication_record record join tblapplication_user b on record.user_id=b.id join tblapplication_emi emi on record.applicationno=emi.application_no join tblapplication_emi_details details on details.emi_id= emi.emi_id join tblapplication_emi_payment payment on payment.application_no= emi.application_no where record.isdeleted= false and record.isfor_reloan= false order by fs_date";
