        public const string GetLoanHistoryLatest = "select distinct tar.user_id, tar.applicationno, COALESCE(to_char(tar.completeon, 'DD Mon YYYY'),'')completeon, terms.term_name,tar.disbursement_date, tacd.contract_ref_no, tapvd.approved_loan_amount,coalesce((select coalesce(sum(tblapplication_emi_details.emi_amount),0) from tblapplication_emi_details where tblapplication_emi_details.emi_id = tae.emi_id),0) as emiamount ,coalesce((select coalesce(sum(tblapplication_emi_payment.paid_amount),0) from tblapplication_emi_payment where tblapplication_emi_payment.application_no = taep.application_no and tblapplication_emi_payment.paymentapproved=true),0) as paid_amount, (coalesce((select coalesce(sum(tblapplication_emi_payment.penalty_amount),0) from tblapplication_emi_payment where tblapplication_emi_payment.application_no = taep.application_no and tblapplication_emi_payment.paymentapproved=true),0)+coalesce((select coalesce(sum(tbl_deferment_pay.late_penalty_amount),0) from tbl_deferment_pay where tbl_deferment_pay.emi_id = tae.emi_id),0)) as penalty_amount,(SELECT to_char(paid_on,'dd-MM-yyyy') as paid_on FROM tblapplication_emi_payment where tblapplication_emi_payment.application_no= taep.application_no ORDER BY paid_on::timestamp DESC LIMIT 1) from tblapplication_record tar join tblapplication_personal_verification_details tapvd on tar.applicationno= tapvd.application_no join tblterms terms on tar.term = terms.id join tbl_application_contract_details tacd on tar.applicationno = tacd.application_no join tblapplication_emi tae on tar.applicationno = tae.application_no join tblapplication_emi_payment taep on tae.application_no = taep.application_no join tblapplication_emi_details taed on taed.emi_id = tae.emi_id where tar.user_id = '{0}' order by tar.disbursement_date desc;";
        public const string GetDisbursementCollectionNew = "Select (SELECT round(COALESCE(SUM(tapvd.approved_loan_amount), 0), 2) as New_Amount from tblapplication_record tar join tblapplication_personal_verification_details tapvd on tar.applicationno = tapvd.application_no join tblapplication_emi tae on tae.application_no = tar.applicationno where tar.isfor_reloan = false and tar.is_preterm = false and tae.disbursement_date::date between '{0}'::date and '{1}'::date), (SELECT round(COALESCE(SUM(tapvd.approved_loan_amount), 0), 2) as Reloan_Amount from tblapplication_record tar join tblapplication_personal_verification_details tapvd on tar.applicationno = tapvd.application_no join tblapplication_emi tae on tae.application_no = tar.applicationno where tar.isfor_reloan = true and tar.is_preterm = false and tae.disbursement_date::date between '{0}'::date and '{1}'::date), (Select (SELECT round(COALESCE(SUM(tapvd.approved_loan_amount), 0), 2) as New_Amount from tblapplication_record tar join tblapplication_personal_verification_details tapvd on tar.applicationno = tapvd.application_no join tblapplication_emi tae on tae.application_no = tar.applicationno where tar.isfor_reloan = false and tar.is_preterm = false and tae.disbursement_date::date between '{0}'::date and '{1}'::date) + (SELECT round(COALESCE(SUM(tapvd.approved_loan_amount), 0), 2) as Reloan_Amount from tblapplication_record tar join tblapplication_personal_verification_details tapvd on tar.applicationno = tapvd.application_no join tblapplication_emi tae on tae.application_no = tar.applicationno where tar.isfor_reloan = true and tar.is_preterm = false and tae.disbursement_date::date between '{0}'::date and '{1}'::date) as total_peso), (SELECT Count(tapvd.approved_loan_amount) as New_Loan_No from tblapplication_record tar join tblapplication_personal_verification_details tapvd on tar.applicationno = tapvd.application_no join tblapplication_emi tae on tae.application_no = tar.applicationno where tar.isfor_reloan 