        public const string InsertApplicantDetails = "INSERT INTO tblapplication_user (first_name,middle_name,last_name,personalemail,user_password, personalcontactno) VALUES ('{0}', '{1}', '{2}', '{3}', '{4}', '{5}');SELECT currval('tblapplication_user_id_seq');";
        public const string InsertApplication_RecordNew = "INSERT INTO tblapplication_record (user_id) VALUES ({0});SELECT currval('tblapplication_record_applicationno_seq');";
        public const string GetApplicationUserNew = "Select app.applicationno,usr.id, usr.personalemail, usr.user_password from tblapplication_user usr inner join tblapplication_record app on usr.id=app.user_id where usr.personalemail='{0}' and usr.user_password='{1}' and usr.ismobile=false order by app.applicationno desc limit 1";
        public const string GetUserDetailsById = "Select * from tblapplication_record where user_id='{0}' order by applicationno desc limit 1;";
        public const string GetOfficerId = "Select usr.userfullname,map.defaulter_userid from tbl_application_defaulter_mapping map join ct_user usr on map.defaulter_userid=usr.userid inner join tbl_team_agent_mapping team on team.agent_id=map.defaulter_userid where map.created_on::date between '{0}'::date and '{1}'::date and team.tl_id='{2}' group by map.defaulter_userid, usr.userfullname";
        public const string GetNODefaulterMonthlyByOfficerNew = "Select count(map.application_no) as defaulter_userid_no  from tbl_application_defaulter_mapping map join ct_user usr on map.defaulter_userid=usr.userid where map.created_on::date between '{0}'::date and '{1}'::date and map.defaulter_userid= '{2}' group by map.defaulter_userid, usr.userfullname";
        public const string GetLoanPrincipleMonthlyByOfficerNew = "select round(coalesce(sum(ted.balanceamount),0),2)as loan_principle from tblapplication_emi_details ted left join tblapplication_emi ae on ae.emi_id = ted.emi_id left join tbl_application_defaulter_mapping adm on adm.application_no=ae.application_no inner join ct_user usr on adm.defaulter_userid=usr.userid where ted.emi_date::date between '{0}'::date and '{1}'::date and adm.defaulter_userid= '{2}' group by adm.defaulter_userid,usr.userfullname;";
        public const string GetOutstandingBalanceMonthlyByOfficerNew = "select round (coalesce(sum(ted.balanceamount),0),2) as outstanding_amount from tblapplication_emi_details ted left join tblapplication_emi ae on ae.emi_id = ted.emi_id left join tbl_application_defaulter_mapping adm on adm.application_no=ae.application_no inner join ct_user usr on adm.defaulter_userid=usr.userid where ted.emi_date <= current_date and ted.emi_date::date between '{0}'::date and '{1}'::date and adm.defaulter_userid= '{2}' group by adm.defaulter_userid,usr.userfullname;";
