        public const string GetTLSalesData = "SELECT (SELECT Count(taedd.emi_amount)  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date='{0}'::date and map.agent_id='{1}') AS TotalMaturity,(SELECT coalesce(round(SUM(taedd.emi_amount),2),0)  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date = '{0}'::date and map.agent_id='{1}') AS TotalMaturityAmount,(SELECT Count(taedd.paidamount) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date ='{0}'::date and taedd.paidamount>0 and map.agent_id='{1}') AS Totalpaid,(SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date ='{0}'::date and map.agent_id='{1}' ) AS TotalpaidAmount,(CAST(((SELECT cast(Count(taedd.paidamount) as numeric(10,2)) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date ='{0}'::date and taedd.paidamount>0 and map.agent_id='{1}' )/(SELECT CASE WHEN Count(taedd.emi_amount)=0 then 1.0 else cast(Count(taedd.emi_amount) as numeric(10,2)) end  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date ='{0}'::date and  map.agent_id='{1}'))as numeric(10,2))*100) AS efficiency_no,Round((((SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd  inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date ='{0}'::date and  map.agent_id='{1}')/(SELECT CASE WHEN SUM(taedd.emi_amount)=0 then 1 else SUM(taedd.emi_amount) end FROM tblapplication_emi_details taedd  inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id  where taedd.emi_date::date ='{0}'::date and  map.agent_id='{1}'))*100),2) AS efficiency_amount,(SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.is_preterm = true and emi.disbursement_date::date ='{0}'::date and map.agent_id='{1}' ) AS Preterm_No,(SELECT coalesce(round(SUM(tapvd.approved_loan_amount-((tapvd.approved_loan_amount*terms.admin_fee)/100)),2),0) FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no join tblterms terms on terms.id = tar.term inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.is_preterm = true and emi.disbursement_date::date ='{0}'::date and map.agent_id='{1}') AS Preterm_Amount, (SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no  inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.isfor_reloan= true and emi.disbursement_date::date ='{0}'::date and map.agent_id='{1}') AS Reloan_No,(SELECT coalesce(round(SUM(tapvd.approved_loan_amount-((tapvd.approved_loan_amount*terms.admin_fee)/100)),2),0) FROM  tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no join tblterms terms on terms.id = tar.term inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.isfor_reloan = true and emi.disbursement_date::date ='{0}'::date and map.agent_id='{1}') AS Reloan_Amount;";
        public const string GetTLSalesData_Weekly = "SELECT distinct (SELECT Count(taedd.emi_amount)  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS TotalMaturity,(SELECT coalesce(round(SUM(taedd.emi_amount),2),0)  FROM tblapplication_emi_details taedd  inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS TotalMaturityAmount,(SELECT Count(taedd.paidamount) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and taedd.paidamount>0 and map.agent_id='{2}') AS Totalpaid,(SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd  inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS TotalpaidAmount,(CAST(((SELECT cast(Count(taedd.paidamount) as numeric(18,2)) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and taedd.paidamount>0 and map.agent_id='{2}')/(SELECT CASE WHEN Count(taedd.emi_amount)=0 then 1.0 else cast(Count(taedd.emi_amount) as numeric(18,2)) end  FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}'))as numeric(18,2))*100) AS efficiency_no,Round((((SELECT coalesce(SUM(taedd.paidamount),0) FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}')/(SELECT CASE WHEN SUM(taedd.emi_amount)=0 then 1 else SUM(taedd.emi_amount) end FROM tblapplication_emi_details taedd inner join tblapplication_emi emi on taedd.emi_id=emi.emi_id inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where taedd.emi_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}'))*100),2) AS efficiency_amount,(SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.is_preterm = true and emi.disbursement_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS Preterm_No,(SELECT round(SUM(tapvd.approved_loan_amount-((tapvd.approved_loan_amount*terms.admin_fee)/100)),2) FROM     tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no join tblterms terms on terms.id = tar.term inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.is_preterm = true and emi.disbursement_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS Preterm_Amount,(SELECT Count(tapvd.approved_loan_amount)  FROM tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no inner join tblapplication_emi emi on tar.applicationno=emi.application_no inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.isfor_reloan= true and emi.disbursement_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS Reloan_No,(SELECT coalesce(round(SUM(tapvd.approved_loan_amount-((tapvd.approved_loan_amount*terms.admin_fee)/100)),2),0) FROM     tblapplication_personal_verification_details tapvd left join tblapplication_record tar on tar.applicationno = tapvd.application_no inner join tblapplication_emi emi on tar.applicationno=emi.application_no join tblterms terms on terms.id = tar.term inner join tblemi_collection_agent_mapping map on emi.emi_id=map.emi_id where tar.isfor_reloan = true and emi.disbursement_date::date between '{0}'::date and '{1}'::date and map.agent_id='{2}') AS Reloan_Amount from ct_user us left join tblemi_collection_agent_mapping tcam on tcam.agent_id = us.userid where us.userid = '{2}';";
        public const string GetDefaulterUserData = "SELECT t_a_d_m.created_by,u.userid,u.userfullname,cty.cityname , cty.cityid, bar.barangay_name, bar.id, prov.province_name, prov.province_id, t_a_r.applicationno , first_name, last_name, middle_name, personalemail,jumioreference,facemapstatus, personalcontactno, t_a_r.address, t_a_r.zipcode FROM tblapplication_record t_a_r join tblapplication_user b on t_a_r.user_id=b.id left join public.tbl_application_defaulter_mapping t_a_d_m on t_a_d_m.application_no = t_a_r.applicationno left join public.ct_user u on u.userid= t_a_d_m.created_by left join public.tblcity cty on t_a_r.city=cty.cityid left join public.tblprovince prov on t_a_r.province=prov.province_id left join public.tblbarangay bar on t_a_r.barangay=bar.id where t_a_d_m.created_by='{0}';";
