        public const string GetPaymentListByNameLatest = "select distinct emidetails.emi_amount, emi.application_no, appRecord.termtype as termtypeid, t_t.termtype, emi.emi_id, emidetails.paidamount,emidetails.emi_detail_id, concat(((now()::date)-(select a.emi_date from tblapplication_emi_details a where a.emi_id=emi.emi_id and paidamount=0 and emi_amount!=0 order by emi_detail_id limit 1 ))) as aging, emi.reference_no, to_char(appRecord.dateapplied,'DD-MM-YYYY') as dateapplied, concat(first_name,' ',middle_name,' ',last_name) as full_name, personalemail,jumioreference,facemapstatus, personalcontactno,tcd.contract_ref_no,appRecord.ispickedforcollector,'3' as priority ,((select coalesce(sum(emi_amount),0) from tblapplication_emi_details where emi_id = emi.emi_id  and emi_date <= current_date)-(select coalesce(sum(paidamount),0) from tblapplication_emi_details where emi_id = emi.emi_id and emi_date <= current_date)) as balanceamount,morning_time,noon_time,emidetails.emi_date,'2' as sortingorder from tblapplication_emi_details emidetails join tblapplication_emi emi on emi.emi_id=emidetails.emi_id join tblapplication_record appRecord on appRecord.applicationno= emi.application_no join tblapplication_user b on appRecord.user_id=b.id join tblterm_type t_t on appRecord.termtype = t_t.id left join tbl_application_contract_details tcd on tcd.application_no= appRecord.applicationno where  appRecord.isdefaulter=false and appRecord.is_pay=false and lower(concat(first_name,' ',middle_name,' ',last_name)) like lower('%{0}%') and emidetails.emi_amount!=0 and appRecord.ispretermgenerated=false order by sortingorder;";
