ft join tbl_application_contract_details tacd on t_a_r.applicationno =tacd.application_no left join tblapplication_emi as t_a_e on t_a_e.application_no=t_a_r.applicationno join tblapplication_emi_details taed on taed.emi_id=t_a_e.emi_id left  join tblapplication_ptp_details as t_a_p_d on t_a_p_d.application_on=t_a_r.applicationno  left join ct_user usr on t_a_r.verify_by = usr.userid left join ct_user usrs on t_a_r.checked_by = usrs.userid join tblterms terms on t_a_r.term = terms.id join tblterm_type t_t on t_a_r.termtype = t_t.id join tblapplication_personal_verification_details t_a_p_v_d on t_a_p_v_d.application_no = t_a_r.applicationno where t_a_r.applicationno='{0}' order by aging desc limit 1; ";
