        public const string GetLoanDetailListByDate = "select taed.emi_amount,t_a_r.user_id, terms.term_name, terms.interest_rate, terms.late_penalty, terms.late_rate, ((select coalesce(sum(emi_amount),0) from tblapplication_emi_details where emi_id = t_a_e.emi_id)-(select coalesce(sum(paidamount),0) from tblapplication_emi_details where emi_id = t_a_e.emi_id)) as totalbalanceamount,personalemail,jumioreference,facemapstatus,t_t.termtype as termtypename, (('{1}'::date) - taed.emi_date) as aging,t_a_r.verify_by, t_a_r.checked_by, t_a_r.relativename, t_a_r.relationwithrelative, t_a_r.relativecontactno, to_char(t_a_p_d.current_date_ptp,'DD-MM-YYYY') as current_date_ptp,  t_a_p_v_d.family_name1, taed.balanceamount, t_a_p_v_d.family_contact1,t_a_p_v_d.family_relation1,t_a_p_v_d.family_name2,t_a_p_v_d.family_contact2,t_a_p_v_d.family_relation2, t_a_p_v_d.approved_loan_amount, taed.emi_principal, first_name, middle_name, last_name, personalcontactno,t_a_r.applicationno,t_a_e.reference_no,t_a_r.termtype,t_a_r.term, usr.username as verifier, usrs.username as checker, to_char(t_a_e.disbursement_date,'DD-MM-YYYY') as disbursement_date,to_char(t_a_p_d.date_paid,'DD-MM-YYYY') as date_paid,t_a_p_d.best_time_callback, t_a_p_d.non_payment_reason,to_char(t_a_p_d.current_date_ptp,'DD-MM-YYYY') as current_date_ptp, t_a_p_d.current_amount_ptp,t_a_p_d.other_remarks,tacd.contract_ref_no,t_a_e.emi_id,(Select sum(taed.balanceamount) from  tblapplication_emi_details as taed where taed.emi_id=t_a_e.emi_id and taed.emi_date::date<='{1}'::date) as due_amount,(Select to_char(taed.emi_date,'DD-MM-YYYY') as emi_date from  tblapplication_emi_details as taed where taed.emi_id=t_a_e.emi_id and taed.emi_amount!=taed.paidamount and taed.emi_principal!=0 and taed.emi_date::date<='{1}'::date limit 1) from tblapplication_record as t_a_r  join tblapplication_user b on t_a_r.user_id=b.id join tbl_application_contract_details tacd on t_a_r.applicationno =tacd.application_no left join tblapplication_emi as t_a_e on t_a_e.application_no=t_a_r.applicationno join tblapplication_emi_details taed on taed.emi_id=t_a_e.emi_id left  join tblapplication_ptp_details as t_a_p_d on t_a_p_d.application_on=t_a_r.applicationno  left join ct_user usr on t_a_r.verify_by = usr.userid left join ct_user usrs on t_a_r.checked_by = usrs.userid join tblterms terms on t_a_r.term = terms.id join tblterm_type t_t on t_a_r.termtype = t_t.id join tblapplication_personal_verification_details t_a_p_v_d on t_a_p_v_d.application_no = t_a_r.applicationno where t_a_r.applicationno='{0}' and taed.emi_principal!=0  order by aging desc limit 1;--order by t_a_p_d.ptp_id desc limit 1;";
