        public const string GetDefaulterReportDuration = "select distinct taed.emi_detail_id,taed.emi_date, ar.applicationno, personalcontactno, personalemail,jumioreference,facemapstatus, first_name, middle_name,acd.defaulter_userid,last_name,to_char(ar.dateapplied,'DD-MM-YYYY') as dateapplied,emi.reference_no,((now()::date) - taed.emi_date) as aging,(SELECT current_date_ptp FROM tblapplication_ptp_details  where tblapplication_ptp_details.application_on=ar.applicationno ORDER BY current_date_ptp DESC LIMIT 1) as ptp_date,coalesce((select coalesce(sum(tblapplication_emi_details.balanceamount),0) from tblapplication_emi_details where tblapplication_emi_details.emi_id = t_a_e.emi_id and tblapplication_emi_details.emi_date <= current_date),0) as outstanding_amount,DATE_PART('day', now() - acd.created_on) as aging1, t_t.termtype  from tblapplication_record ar join tblapplication_user b on ar.user_id=b.id join tblterm_type t_t on ar.termtype = t_t.id join tbl_application_defaulter_mapping acd on acd.application_no=ar.applicationno join tblapplication_emi emi on emi.application_no=ar.applicationno left join tblapplication_emi t_a_e on t_a_e.application_no= ar.applicationno join tblapplication_emi_details taed on taed.emi_id = emi.emi_id where ar.isdefaulter=true and ar.is_agency=false and taed.emi_amount>0 and acd.defaulter_userid='{0}' and acd.created_on::date between '{1}'::date and '{2}'::date order by ptp_date;";
        public const string DefaulterReportNewQuery = "select coalesce((Select count(application_no) as defaulter_userid  from tbl_application_defaulter_mapping a join tblapplication_record tar on a.application_no=tar.applicationno where created_on::date between '{0}'::date and '{1}'::date and defaulter_userid='{2}' and tar.isdefaulter=true and tar.is_agency=false),0) defaulter_userid ,coalesce((select ROUND(SUM((ted.balanceamount/(1+(terms.interest_rate/100)))),0) as outstanding_loan_principle from tblapplication_record tar join tblapplication_emi tae on tar.applicationno = tae.application_no join tblapplication_emi_details ted on ted.emi_id= tae.emi_id left join tblapplication_emi ae on ae.emi_id = ted.emi_id join tbl_application_defaulter_mapping adm on adm.application_no= ae.application_no join tblterms terms on tar.term = terms.id where adm.created_on::date between '{0}'::date and '{1}'::date and adm.defaulter_userid='{2}' and tar.isdefaulter=true and tar.is_agency=false),0)outstanding_loan_principle,coalesce((select round (coalesce(sum(ted.balanceamount),0),2) as outstanding_amount from  tblapplication_emi_details ted left join tblapplication_emi ae on ae.emi_id = ted.emi_id left join tbl_application_defaulter_mapping adm on adm.application_no=ae.application_no join tblapplication_record tar on ae.application_no=tar.applicationno where adm.created_on::date between '{0}'::date and '{1}'::date and adm.defaulter_userid='{2}' and tar.isdefaulter=true and tar.is_agency=false),0)outstanding_amount,coalesce((SELECT  count(DISTINCT adm.application_no) as non_starter from tbl_application_defaulter_mapping adm join tblapplication_record tar on adm.application_no= tar.applicationno join tblapplication_emi tae on tae.application_no= adm.application_no join tblapplication_emi_details taed on tae.emi_id = taed.emi_id where adm.application_no not in (Select application_no from tblapplication_emi_payment  where paymentapproved=true) and adm.created_on::date between '{0}'::date and '{1}'::date and adm.defaulter_userid='{2}' and tar.isdefaulter=true and tar.is_agency=false),0)non_starter,coalesce((select count(tep.application_no) as Partial_Payment_No from tbl_application_defaulter_mapping tdm left join tblapplication_emi_payment tep on tdm.application_no = tep.application_no join tblapplication_record tar on tdm.application_no=tar.applicationno where tep.is_pay = false and tep.is_partial = true and tep.paymentapproved = true and tep.updatedon::date between '{0}'::date and '{1}'::date and tdm.defaulter_userid='{2}' and tar.isdefaulter=true and tar.is_agency=false),0)Partial_Payment_No,coalesce((select count(ar.applicationno) as Defaulter_Collection from tblapplication_record ar left join tbl_application_defaulter_mapping adm on adm.application_no=ar.applicationno where ar.resume_to_collector = true and  ar.resumetocollector_date::date between '{0}'::date and '{1}'::date and adm.defaulter_userid='{2}' and ar.isdefaulter=false and ar.is_agency=false),0)Defaulter_Collection";
